public void testSimpleConversion_oe() throws Exception {
        final String[] message= {
            "from String",
            "from String",
            "from String",
            "from String",
            "from String",
            "from String",
            "from String",
            "from Byte",
            "from Short",
            "from Integer",
            "from Long",
            "from Float",
            "from Double"
        };

        final Object[] input = {
            String.valueOf(Float.MIN_VALUE),
            "-17.2",
            "-1.1",
            "0.0",
            "1.1",
            "17.2",
            String.valueOf(Float.MAX_VALUE),
            new Byte((byte)7),
            new Short((short)8),
            new Integer(9),
            new Long(10),
            new Float(11.1),
            new Double(12.2),
        };

        final Float[] expected = {
            new Float(Float.MIN_VALUE),
            new Float(-17.2),
            new Float(-1.1),
            new Float(0.0),
            new Float(1.1),
            new Float(17.2),
            new Float(Float.MAX_VALUE),
            new Float(7),
            new Float(8),
            new Float(9),
            new Float(10),
            new Float(11.1),
            new Float(12.2)
        };

        for(int i=0;i<expected.length;i++) {
            assertEquals(message[i] + " to Float",expected[i].floatValue(),(converter.convert(Float.class,input[i])).floatValue(),0.00001);
            assertEquals(message[i] + " to float",expected[i].floatValue(),(converter.convert(Float.TYPE,input[i])).floatValue(),0.00001);
            assertEquals(message[i] + " to null type",expected[i].floatValue(),((Float)(converter.convert(null,input[i]))).floatValue(),0.00001);
        }
    }

